sealed class NearRpcActionView {
  const NearRpcActionView();

  factory NearRpcActionView.fromJson(dynamic json) {
    if (json is String) {
      return switch (json) {
        'CreateAccount' => const NearRpcActionViewCreateAccount(),
        _ =>
          throw OnChainErrors.nearPlugin(
            'NearRpcActionView',
            reason: 'Unknown NearRpcActionView: $json',
          ),
      };
    }
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('DeployContract')) {
        return NearRpcActionViewDeployContract.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DeployContract'),
        );
      }
      if (map.hasValue('FunctionCall')) {
        return NearRpcActionViewFunctionCall.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('FunctionCall'),
        );
      }
      if (map.hasValue('Transfer')) {
        return NearRpcActionViewTransfer.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('Transfer'),
        );
      }
      if (map.hasValue('Stake')) {
        return NearRpcActionViewStake.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('Stake'),
        );
      }
      if (map.hasValue('AddKey')) {
        return NearRpcActionViewAddKey.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('AddKey'),
        );
      }
      if (map.hasValue('DeleteKey')) {
        return NearRpcActionViewDeleteKey.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DeleteKey'),
        );
      }
      if (map.hasValue('DeleteAccount')) {
        return NearRpcActionViewDeleteAccount.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DeleteAccount'),
        );
      }
      if (map.hasValue('Delegate')) {
        return NearRpcActionViewDelegate.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('Delegate'),
        );
      }
      if (map.hasValue('DelegateV2')) {
        return NearRpcActionViewDelegateV2.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DelegateV2'),
        );
      }
      if (map.hasValue('DeployGlobalContract')) {
        return NearRpcActionViewDeployGlobalContract.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DeployGlobalContract'),
        );
      }
      if (map.hasValue('DeployGlobalContractByAccountId')) {
        return NearRpcActionViewDeployGlobalContractByAccountId.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'DeployGlobalContractByAccountId',
          ),
        );
      }
      if (map.hasValue('UseGlobalContract')) {
        return NearRpcActionViewUseGlobalContract.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('UseGlobalContract'),
        );
      }
      if (map.hasValue('UseGlobalContractByAccountId')) {
        return NearRpcActionViewUseGlobalContractByAccountId.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('UseGlobalContractByAccountId'),
        );
      }
      if (map.hasValue('DeterministicStateInit')) {
        return NearRpcActionViewDeterministicStateInit.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('DeterministicStateInit'),
        );
      }
      if (map.hasValue('TransferToGasKey')) {
        return NearRpcActionViewTransferToGasKey.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('TransferToGasKey'),
