/// Describes the error for validating a list of actions.
sealed class NearRpcActionsValidationError {
  const NearRpcActionsValidationError();

  factory NearRpcActionsValidationError.fromJson(dynamic json) {
    if (json is String) {
      return switch (json) {
        'DeleteActionMustBeFinal' =>
          const NearRpcActionsValidationErrorDeleteActionMustBeFinal(),
        'IntegerOverflow' =>
          const NearRpcActionsValidationErrorIntegerOverflow(),
        'FunctionCallZeroAttachedGas' =>
          const NearRpcActionsValidationErrorFunctionCallZeroAttachedGas(),
        'DelegateActionMustBeOnlyOne' =>
          const NearRpcActionsValidationErrorDelegateActionMustBeOnlyOne(),
        'GasKeyFunctionCallAllowanceNotAllowed' =>
          const NearRpcActionsValidationErrorGasKeyFunctionCallAllowanceNotAllowed(),
        'FunctionCallEmptyMethodName' =>
          const NearRpcActionsValidationErrorFunctionCallEmptyMethodName(),
        'MalformedUniversalStateInit' =>
          const NearRpcActionsValidationErrorMalformedUniversalStateInit(),
        'WithdrawFromGasKeyNotAllowedInDelegate' =>
          const NearRpcActionsValidationErrorWithdrawFromGasKeyNotAllowedInDelegate(),
        _ =>
          throw OnChainErrors.nearPlugin(
            'NearRpcActionsValidationError',
            reason: 'Unknown NearRpcActionsValidationError: $json',
          ),
      };
    }
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('TotalPrepaidGasExceeded')) {
        return NearRpcActionsValidationErrorTotalPrepaidGasExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('TotalPrepaidGasExceeded'),
        );
      }
      if (map.hasValue('TotalNumberOfActionsExceeded')) {
        return NearRpcActionsValidationErrorTotalNumberOfActionsExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('TotalNumberOfActionsExceeded'),
        );
      }
      if (map.hasValue('AddKeyMethodNamesNumberOfBytesExceeded')) {
        return NearRpcActionsValidationErrorAddKeyMethodNamesNumberOfBytesExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'AddKeyMethodNamesNumberOfBytesExceeded',
          ),
        );
      }
      if (map.hasValue('AddKeyMethodNameLengthExceeded')) {
        return NearRpcActionsValidationErrorAddKeyMethodNameLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'AddKeyMethodNameLengthExceeded',
          ),
        );
      }
      if (map.hasValue('InvalidAccountId')) {
        return NearRpcActionsValidationErrorInvalidAccountId.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('InvalidAccountId'),
        );
      }
      if (map.hasValue('ContractSizeExceeded')) {
        return NearRpcActionsValidationErrorContractSizeExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('ContractSizeExceeded'),
        );
      }
      if (map.hasValue('FunctionCallMethodNameLengthExceeded')) {
        return NearRpcActionsValidationErrorFunctionCallMethodNameLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'FunctionCallMethodNameLengthExceeded',
          ),
        );
      }
      if (map.hasValue('FunctionCallArgumentsLengthExceeded')) {
        return NearRpcActionsValidationErrorFunctionCallArgumentsLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'FunctionCallArgumentsLengthExceeded',
          ),
        );
      }
      if (map.hasValue('UnsuitableStakingKey')) {
        return NearRpcActionsValidationErrorUnsuitableStakingKey.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('UnsuitableStakingKey'),
        );
      }
      if (map.hasValue('UnsupportedProtocolFeature')) {
        return NearRpcActionsValidationErrorUnsupportedProtocolFeature.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('UnsupportedProtocolFeature'),
        );
      }
      if (map.hasValue('InvalidDeterministicStateInitReceiver')) {
        return NearRpcActionsValidationErrorInvalidDeterministicStateInitReceiver.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'InvalidDeterministicStateInitReceiver',
          ),
        );
      }
      if (map.hasValue('DeterministicStateInitKeyLengthExceeded')) {
        return NearRpcActionsValidationErrorDeterministicStateInitKeyLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'DeterministicStateInitKeyLengthExceeded',
