        );
      }
      if (map.hasValue('AddGasKeyWithNonZeroBalance')) {
        return NearRpcActionsValidationErrorAddGasKeyWithNonZeroBalance.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('AddGasKeyWithNonZeroBalance'),
        );
      }
      if (map.hasValue('TotalNumberOfDeployActionsExceeded')) {
        return NearRpcActionsValidationErrorTotalNumberOfDeployActionsExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'TotalNumberOfDeployActionsExceeded',
          ),
        );
      }
      if (map.hasValue('InvalidUniversalStateInitReceiver')) {
        return NearRpcActionsValidationErrorInvalidUniversalStateInitReceiver.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'InvalidUniversalStateInitReceiver',
          ),
        );
      }
      if (map.hasValue('UniversalStateInitKeyLengthExceeded')) {
        return NearRpcActionsValidationErrorUniversalStateInitKeyLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'UniversalStateInitKeyLengthExceeded',
          ),
        );
      }
      if (map.hasValue('UniversalStateInitValueLengthExceeded')) {
        return NearRpcActionsValidationErrorUniversalStateInitValueLengthExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
            'UniversalStateInitValueLengthExceeded',
          ),
        );
      }
      if (map.hasValue('RemovedProtocolFeature')) {
        return NearRpcActionsValidationErrorRemovedProtocolFeature.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('RemovedProtocolFeature'),
        );
      }
      if (map.hasValue('TotalNumberOfStateInitKeysExceeded')) {
        return NearRpcActionsValidationErrorTotalNumberOfStateInitKeysExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>(
