sealed class NearRpcCompilationError {
  const NearRpcCompilationError();

  factory NearRpcCompilationError.fromJson(dynamic json) {
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('CodeDoesNotExist')) {
        return NearRpcCompilationErrorCodeDoesNotExist.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('CodeDoesNotExist'),
        );
      }
      if (map.hasValue('PrepareError')) {
        return NearRpcCompilationErrorPrepareError(
          NearRpcPrepareError.fromJson(map['PrepareError']),
        );
      }
      if (map.hasValue('WasmerCompileError')) {
        return NearRpcCompilationErrorWasmerCompileError.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('WasmerCompileError'),
        );
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcCompilationError',
      reason: 'Cannot parse NearRpcCompilationError from $json',
    );
