          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('AccessKeyNotFound')) {
        return NearRpcInvalidAccessKeyErrorAccessKeyNotFound.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('AccessKeyNotFound'),
