      if (map.hasValue('NotEnoughAllowance')) {
        return NearRpcInvalidAccessKeyErrorNotEnoughAllowance.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NotEnoughAllowance'),
        );
