sealed class NearRpcInvalidTxError {
  const NearRpcInvalidTxError();

  factory NearRpcInvalidTxError.fromJson(dynamic json) {
    if (json is String) {
      return switch (json) {
        'InvalidSignature' => const NearRpcInvalidTxErrorInvalidSignature(),
        'CostOverflow' => const NearRpcInvalidTxErrorCostOverflow(),
        'InvalidChain' => const NearRpcInvalidTxErrorInvalidChain(),
        'Expired' => const NearRpcInvalidTxErrorExpired(),
        'InvalidTransactionVersion' =>
          const NearRpcInvalidTxErrorInvalidTransactionVersion(),
