      if (map.hasValue('InvalidSignerId')) {
        return NearRpcInvalidTxErrorInvalidSignerId.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('InvalidSignerId'),
        );
      }
      if (map.hasValue('SignerDoesNotExist')) {
        return NearRpcInvalidTxErrorSignerDoesNotExist.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('SignerDoesNotExist'),
        );
      }
      if (map.hasValue('InvalidNonce')) {
        return NearRpcInvalidTxErrorInvalidNonce.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('InvalidNonce'),
        );
      }
      if (map.hasValue('NonceTooLarge')) {
        return NearRpcInvalidTxErrorNonceTooLarge.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NonceTooLarge'),
        );
      }
      if (map.hasValue('InvalidReceiverId')) {
        return NearRpcInvalidTxErrorInvalidReceiverId.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('InvalidReceiverId'),
        );
      }
      if (map.hasValue('NotEnoughBalance')) {
        return NearRpcInvalidTxErrorNotEnoughBalance.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NotEnoughBalance'),
        );
      }
      if (map.hasValue('LackBalanceForState')) {
        return NearRpcInvalidTxErrorLackBalanceForState.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('LackBalanceForState'),
        );
