      }
      if (map.hasValue('TransactionSizeExceeded')) {
        return NearRpcInvalidTxErrorTransactionSizeExceeded.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('TransactionSizeExceeded'),
        );
      }
      if (map.hasValue('StorageError')) {
