/// A versioned struct that contains all information needed to assign accounts to shards.
///
/// Because of re-sharding, the chain may use different shard layout to split shards at different
/// times. Currently, `ShardLayout` is stored as part of `EpochConfig`, which is generated each
/// epoch given the epoch protocol version. In mainnet/testnet, we use two shard layouts since
/// re-sharding has only happened once. It is stored as part of genesis config, see
/// default_simple_nightshade_shard_layout() Below is an overview for some important
/// functionalities of ShardLayout interface.
sealed class NearRpcShardLayout {
  const NearRpcShardLayout();

  factory NearRpcShardLayout.fromJson(dynamic json) {
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('V0')) {
        return NearRpcShardLayoutV02(
          NearRpcShardLayoutV0.fromJson(
            map.valueEnsureAsMap<String, dynamic>('V0'),
          ),
        );
      }
      if (map.hasValue('V1')) {
        return NearRpcShardLayoutV12(
          NearRpcShardLayoutV1.fromJson(
            map.valueEnsureAsMap<String, dynamic>('V1'),
          ),
        );
      }
      if (map.hasValue('V2')) {
        return NearRpcShardLayoutV22(
          NearRpcShardLayoutV2.fromJson(
            map.valueEnsureAsMap<String, dynamic>('V2'),
          ),
        );
      }
      if (map.hasValue('V3')) {
        return NearRpcShardLayoutV32(
          NearRpcShardLayoutV3.fromJson(
            map.valueEnsureAsMap<String, dynamic>('V3'),
          ),
        );
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcShardLayout',
      reason: 'Cannot parse NearRpcShardLayout from $json',
    );
  }

  dynamic toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig});
}

