/// Which piece of a shard's state a light-client state proof targets.
///
/// An account that runs a global contract has no local code, so `LocalContractCode` is
/// absent for it. `Account::contract()` says which case applies.
sealed class NearRpcStateProofTarget {
  const NearRpcStateProofTarget();

  factory NearRpcStateProofTarget.fromJson(dynamic json) {
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map['target_type'] == "contract_data" &&
          map.hasValue('account_id') &&
          map.hasValue('key')) {
        return NearRpcStateProofTargetTargetTypeAccountIdKey.fromJson(map);
      }
      if (map['target_type'] == "access_key" &&
          map.hasValue('account_id') &&
          map.hasValue('public_key')) {
        return NearRpcStateProofTargetTargetTypeAccountIdPublicKey.fromJson(
          map,
        );
      }
      if (map['target_type'] == "account" && map.hasValue('account_id')) {
        return NearRpcStateProofTargetTargetTypeAccountId.fromJson(map);
      }
      if (map['target_type'] == "local_contract_code" &&
          map.hasValue('account_id')) {
        return NearRpcStateProofTargetTargetTypeAccountId2.fromJson(map);
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcStateProofTarget',
      reason: 'Cannot parse NearRpcStateProofTarget from $json',
    );
  }

  dynamic toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig});
}

