/// Errors which may occur during working with trie storages, storing
/// trie values (trie nodes and state values) by their hashes.
sealed class NearRpcStorageError {
  const NearRpcStorageError();

  factory NearRpcStorageError.fromJson(dynamic json) {
    if (json is String) {
      return switch (json) {
        'StorageInternalError' =>
          const NearRpcStorageErrorStorageInternalError(),
        'UnexpectedTrieValue' => const NearRpcStorageErrorUnexpectedTrieValue(),
        _ =>
          throw OnChainErrors.nearPlugin(
            'NearRpcStorageError',
            reason: 'Unknown NearRpcStorageError: $json',
          ),
      };
    }
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('MissingTrieValue')) {
        return NearRpcStorageErrorMissingTrieValue(
          NearRpcMissingTrieValue.fromJson(
            map.valueEnsureAsMap<String, dynamic>('MissingTrieValue'),
          ),
        );
      }
      if (map.hasValue('StorageInconsistentState')) {
        return NearRpcStorageErrorStorageInconsistentState(
          (map['StorageInconsistentState'] is num
              ? map['StorageInconsistentState'].toString()
              : map.valueAsString<String>('StorageInconsistentState')),
        );
      }
      if (map.hasValue('FlatStorageBlockNotSupported')) {
        return NearRpcStorageErrorFlatStorageBlockNotSupported(
          (map['FlatStorageBlockNotSupported'] is num
              ? map['FlatStorageBlockNotSupported'].toString()
              : map.valueAsString<String>('FlatStorageBlockNotSupported')),
        );
      }
      if (map.hasValue('MemTrieLoadingError')) {
        return NearRpcStorageErrorMemTrieLoadingError(
          (map['MemTrieLoadingError'] is num
              ? map['MemTrieLoadingError'].toString()
              : map.valueAsString<String>('MemTrieLoadingError')),
        );
