/// Explains why a transaction status request returned a `RpcTransactionError::TimeoutError`:
sealed class NearRpcTimeoutErrorCause {
  const NearRpcTimeoutErrorCause();

  factory NearRpcTimeoutErrorCause.fromJson(dynamic json) {
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map['cause'] == "PENDING" && map.hasValue('status')) {
        return NearRpcTimeoutErrorCauseCauseStatus.fromJson(map);
      }
      if (map['cause'] == "DOES_NOT_TRACK_SHARD" && map.hasValue('shard_id')) {
        return NearRpcTimeoutErrorCauseCauseShardId.fromJson(map);
      }
      if (map['cause'] == "ERROR" && map.hasValue('debug_info')) {
        return NearRpcTimeoutErrorCauseCauseDebugInfo.fromJson(map);
      }
      if (map['cause'] == "NOT_OBSERVED") {
        return NearRpcTimeoutErrorCauseCause.fromJson(map);
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcTimeoutErrorCause',
      reason: 'Cannot parse NearRpcTimeoutErrorCause from $json',
    );
  }

  dynamic toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig});
}

