/// Describes the expected behavior of the node regarding shard tracking.
/// If the node is an active validator, it will also track the shards it is responsible for as a validator.
sealed class NearRpcTrackedShardsConfig {
  const NearRpcTrackedShardsConfig();

  factory NearRpcTrackedShardsConfig.fromJson(dynamic json) {
    if (json is String) {
      return switch (json) {
        'NoShards' => const NearRpcTrackedShardsConfigNoShards(),
        'AllShards' => const NearRpcTrackedShardsConfigAllShards(),
        _ =>
          throw OnChainErrors.nearPlugin(
            'NearRpcTrackedShardsConfig',
            reason: 'Unknown NearRpcTrackedShardsConfig: $json',
          ),
      };
    }
    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('Shards')) {
        return NearRpcTrackedShardsConfigShards(
          map
              .valueEnsureAsList<Map<String, dynamic>>('Shards')
              .map((e) => NearRpcShardUId.fromJson(e))
              .toList(),
        );
      }
      if (map.hasValue('ShadowValidator')) {
        return NearRpcTrackedShardsConfigShadowValidator(
          (map['ShadowValidator'] is num
              ? map['ShadowValidator'].toString()
              : map.valueAsString<String>('ShadowValidator')),
        );
      }
      if (map.hasValue('Schedule')) {
        return NearRpcTrackedShardsConfigSchedule(
          map
              .valueEnsureAsList<dynamic>('Schedule')
              .map(
                (e) =>
                    (e as List)
                        .map((e) => JsonParser.valueAsBigInt<BigInt>(e))
                        .toList(),
              )
              .toList(),
        );
      }
      if (map.hasValue('Accounts')) {
        return NearRpcTrackedShardsConfigAccounts(
          map.valueAsList<List<String>>('Accounts'),
        );
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcTrackedShardsConfig',
      reason: 'Cannot parse NearRpcTrackedShardsConfig from $json',
    );
  }

  dynamic toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig});
}

