    if (json is Map) {
      final map =
          json is Map<String, dynamic> ? json : Map<String, dynamic>.from(json);
      if (map.hasValue('NotEnoughBlocks')) {
        return NearRpcValidatorKickoutReasonNotEnoughBlocks.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NotEnoughBlocks'),
        );
      }
      if (map.hasValue('NotEnoughChunks')) {
        return NearRpcValidatorKickoutReasonNotEnoughChunks.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NotEnoughChunks'),
        );
