      if (map.hasValue('NotEnoughChunkEndorsements')) {
        return NearRpcValidatorKickoutReasonNotEnoughChunkEndorsements.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('NotEnoughChunkEndorsements'),
