      if (map.hasValue('ProtocolVersionTooOld')) {
        return NearRpcValidatorKickoutReasonProtocolVersionTooOld.fromPayload(
          map.valueEnsureAsMap<String, dynamic>('ProtocolVersionTooOld'),
        );
      }
    }
    throw OnChainErrors.nearPlugin(
      'NearRpcValidatorKickoutReason',
      reason: 'Cannot parse NearRpcValidatorKickoutReason from $json',
    );
  }

  dynamic toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig});
