/// A kind of a trap happened during execution of a binary
enum NearRpcWasmTrap {
  unreachable("Unreachable"),
  incorrectCallIndirectSignature("IncorrectCallIndirectSignature"),
  memoryOutOfBounds("MemoryOutOfBounds"),
  callIndirectOOB("CallIndirectOOB"),
  illegalArithmetic("IllegalArithmetic"),
  misalignedAtomicAccess("MisalignedAtomicAccess"),
  indirectCallToNull("IndirectCallToNull"),
  stackOverflow("StackOverflow"),
  genericTrap("GenericTrap");

  final String value;
  const NearRpcWasmTrap(this.value);

  static NearRpcWasmTrap fromJson(dynamic json) {
    final value = json is String ? json : json?.toString();
    return values.firstWhere(
      (e) => e.value == value,
      orElse:
          () =>
              throw OnChainErrors.nearPlugin(
                "NearRpcWasmTrap.lookup",
                reason: "Invalid NearRpcWasmTrap.",
              ),
    );
  }

  String toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig}) =>
      value;
}

