  static NearRpcTimeoutErrorCauseCauseStatusCause fromJson(dynamic json) {
    final value = json is String ? json : json?.toString();
    return values.firstWhere(
      (e) => e.value == value,
      orElse:
          () =>
              throw OnChainErrors.nearPlugin(
                "NearRpcTimeoutErrorCauseCauseStatusCause.lookup",
                reason: "Invalid NearRpcTimeoutErrorCauseCauseStatusCause.",
              ),
    );
  }

  String toJson({JsonifyConfig config = DefaultJsonifyConfig.defaultConfig}) =>
      value;
}

