  /// Account key of the validator signing this AccountData.
  final String accountKey;

  /// ID of the node that handles the account key (aka validator key).
  final String peerId;

  /// Proxy nodes that are directly connected to the validator node
  final List<NearRpcTier1ProxyView> proxies;

  /// UTC timestamp of when the AccountData has been signed.
  final String timestamp;

  const NearRpcAccountDataView({
    required this.accountKey,
    required this.peerId,
    required this.proxies,
    required this.timestamp,
  });

  factory NearRpcAccountDataView.fromJson(Map<String, dynamic> json) {
    return NearRpcAccountDataView(
      accountKey:
          (json['account_key'] is num
              ? json['account_key'].toString()
              : json.valueAsString<String>('account_key')),
      peerId:
          (json['peer_id'] is num
              ? json['peer_id'].toString()
              : json.valueAsString<String>('peer_id')),
      proxies:
          json
              .valueEnsureAsList<Map<String, dynamic>>('proxies')
              .map((e) => NearRpcTier1ProxyView.fromJson(e))
              .toList(),
      timestamp:
          (json['timestamp'] is num
              ? json['timestamp'].toString()
              : json.valueAsString<String>('timestamp')),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'account_key': accountKey,
    'peer_id': peerId,
    'proxies': proxies.map((e) => e.toJson(config: config)).toList(),
    'timestamp': timestamp,
  });
}

