/// Config for the Chunk Distribution Network feature.
/// This allows nodes to push and pull chunks from a central stream.
/// The two benefits of this approach are: (1) less request/response traffic
/// on the peer-to-peer network and (2) lower latency for RPC nodes indexing the chain.
class NearRpcChunkDistributionNetworkConfig {
  final bool? enabled;
  final NearRpcChunkDistributionUris? uris;

  const NearRpcChunkDistributionNetworkConfig({this.enabled, this.uris});

  factory NearRpcChunkDistributionNetworkConfig.fromJson(
    Map<String, dynamic> json,
  ) {
    return NearRpcChunkDistributionNetworkConfig(
      enabled: json.valueAsBool<bool?>('enabled'),
      uris: json.valueTo<NearRpcChunkDistributionUris?, Map<String, dynamic>>(
        key: 'uris',
        parse: (v) => NearRpcChunkDistributionUris.fromJson(v),
      ),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'enabled': enabled,
    'uris': uris?.toJson(config: config),
  });
}

