}

/// Proof that a chunk's certified execution roots are committed by a spice block
/// that a light client can trust via its `light_client_head`.
///
/// `roots_proof` recomputes the certifying block's `chunk_execution_root` from the leaf;
/// `certifying_block_proof` places the certifying block into the head's block merkle tree.
class NearRpcChunkExecutionProofView {
  final NearRpcLightClientBlockLiteView certifyingBlockHeaderLite;
  final List<NearRpcMerklePathItem> certifyingBlockProof;
  final NearRpcChunkExecutionRoots roots;
  final List<NearRpcMerklePathItem> rootsProof;

  const NearRpcChunkExecutionProofView({
    required this.certifyingBlockHeaderLite,
    required this.certifyingBlockProof,
    required this.roots,
    required this.rootsProof,
  });

  factory NearRpcChunkExecutionProofView.fromJson(Map<String, dynamic> json) {
    return NearRpcChunkExecutionProofView(
      certifyingBlockHeaderLite: json
          .valueTo<NearRpcLightClientBlockLiteView, Map<String, dynamic>>(
            key: 'certifying_block_header_lite',
            parse: (v) => NearRpcLightClientBlockLiteView.fromJson(v),
          ),
      certifyingBlockProof:
          json
              .valueEnsureAsList<Map<String, dynamic>>('certifying_block_proof')
              .map((e) => NearRpcMerklePathItem.fromJson(e))
              .toList(),
      roots: json.valueTo<NearRpcChunkExecutionRoots, Map<String, dynamic>>(
        key: 'roots',
        parse: (v) => NearRpcChunkExecutionRoots7.fromJson(v),
      ),
      rootsProof:
          json
              .valueEnsureAsList<Map<String, dynamic>>('roots_proof')
              .map((e) => NearRpcMerklePathItem.fromJson(e))
              .toList(),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'certifying_block_header_lite': certifyingBlockHeaderLite.toJson(
      config: config,
    ),
    'certifying_block_proof':
        certifyingBlockProof.map((e) => e.toJson(config: config)).toList(),
    'roots': roots.toJson(config: config),
    'roots_proof': rootsProof.map((e) => e.toJson(config: config)).toList(),
  });
}

