/// Configuration for a cloud-based archival writer. If this config is present, the writer is enabled and
/// writes chunk-related data based on the tracked shards. This config also controls additional archival
/// behavior such as block data and polling interval.
class NearRpcCloudArchivalWriterConfig {
  /// Determines whether block-related data should be written to cloud storage.
  final bool? archiveBlockData;

  /// Delay between consecutive batches while the writer is catching up, pacing
  final NearRpcDurationAsStdSchemaProvider? catchUpThrottle;

  /// Interval at which the system checks for new blocks or chunks to archive.
  final NearRpcDurationAsStdSchemaProvider? pollingInterval;

  /// Cadence of state snapshots, in epochs. Higher values reduce bucket cost at
  final BigInt? snapshotEveryNEpochs;

  const NearRpcCloudArchivalWriterConfig({
    this.archiveBlockData,
    this.catchUpThrottle,
    this.pollingInterval,
    this.snapshotEveryNEpochs,
  });

  factory NearRpcCloudArchivalWriterConfig.fromJson(Map<String, dynamic> json) {
    return NearRpcCloudArchivalWriterConfig(
      archiveBlockData: json.valueAsBool<bool?>('archive_block_data'),
      catchUpThrottle: json
          .valueTo<NearRpcDurationAsStdSchemaProvider?, Map<String, dynamic>>(
            key: 'catch_up_throttle',
            parse: (v) => NearRpcDurationAsStdSchemaProvider.fromJson(v),
          ),
      pollingInterval: json
          .valueTo<NearRpcDurationAsStdSchemaProvider?, Map<String, dynamic>>(
            key: 'polling_interval',
            parse: (v) => NearRpcDurationAsStdSchemaProvider.fromJson(v),
          ),
      snapshotEveryNEpochs: json.valueAsBigInt<BigInt?>(
        'snapshot_every_n_epochs',
      ),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'archive_block_data': archiveBlockData,
    'catch_up_throttle': catchUpThrottle?.toJson(config: config),
    'polling_interval': pollingInterval?.toJson(config: config),
    'snapshot_every_n_epochs': config.encodeBigint(snapshotEveryNEpochs),
  });
}

/// The configuration for congestion control. More info about congestion [here](https://near.github.io/nearcore/architecture/how/receipt-congestion.html?highlight=congestion#receipt-congestion)
class NearRpcCongestionControlConfigView {
  /// How much gas the chosen allowed shard can send to a 100% congested shard.
  final BigInt? allowedShardOutgoingGas;

  /// How much gas in delayed receipts of a shard is 100% incoming congestion.
  final BigInt? maxCongestionIncomingGas;

  /// How much memory space of all delayed and buffered receipts in a shard is
  final BigInt? maxCongestionMemoryConsumption;

  /// How many missed chunks in a row in a shard is considered 100% congested.
  final BigInt? maxCongestionMissedChunks;

  /// How much gas in outgoing buffered receipts of a shard is 100% congested.
  final BigInt? maxCongestionOutgoingGas;

  /// The maximum amount of gas attached to receipts a shard can forward to
  final BigInt? maxOutgoingGas;

  /// The maximum amount of gas in a chunk spent on converting new transactions to
  final BigInt? maxTxGas;

  /// The minimum gas each shard can send to a shard that is not fully congested.
  final BigInt? minOutgoingGas;

  /// The minimum amount of gas in a chunk spent on converting new transactions
  final BigInt? minTxGas;

  /// Large size limit for outgoing receipts to a shard, used when it's safe
  final BigInt? outgoingReceiptsBigSizeLimit;

  /// The standard size limit for outgoing receipts aimed at a single shard.
  final BigInt? outgoingReceiptsUsualSizeLimit;

  /// How much congestion a shard can tolerate before it stops all shards from
  final double? rejectTxCongestionThreshold;

  const NearRpcCongestionControlConfigView({
    this.allowedShardOutgoingGas,
    this.maxCongestionIncomingGas,
    this.maxCongestionMemoryConsumption,
    this.maxCongestionMissedChunks,
    this.maxCongestionOutgoingGas,
    this.maxOutgoingGas,
    this.maxTxGas,
    this.minOutgoingGas,
    this.minTxGas,
    this.outgoingReceiptsBigSizeLimit,
    this.outgoingReceiptsUsualSizeLimit,
    this.rejectTxCongestionThreshold,
  });

  factory NearRpcCongestionControlConfigView.fromJson(
    Map<String, dynamic> json,
  ) {
    return NearRpcCongestionControlConfigView(
      allowedShardOutgoingGas: json.valueAsBigInt<BigInt?>(
        'allowed_shard_outgoing_gas',
      ),
      maxCongestionIncomingGas: json.valueAsBigInt<BigInt?>(
        'max_congestion_incoming_gas',
      ),
      maxCongestionMemoryConsumption: json.valueAsBigInt<BigInt?>(
        'max_congestion_memory_consumption',
      ),
      maxCongestionMissedChunks: json.valueAsBigInt<BigInt?>(
        'max_congestion_missed_chunks',
      ),
      maxCongestionOutgoingGas: json.valueAsBigInt<BigInt?>(
        'max_congestion_outgoing_gas',
      ),
      maxOutgoingGas: json.valueAsBigInt<BigInt?>('max_outgoing_gas'),
      maxTxGas: json.valueAsBigInt<BigInt?>('max_tx_gas'),
      minOutgoingGas: json.valueAsBigInt<BigInt?>('min_outgoing_gas'),
      minTxGas: json.valueAsBigInt<BigInt?>('min_tx_gas'),
      outgoingReceiptsBigSizeLimit: json.valueAsBigInt<BigInt?>(
        'outgoing_receipts_big_size_limit',
      ),
      outgoingReceiptsUsualSizeLimit: json.valueAsBigInt<BigInt?>(
        'outgoing_receipts_usual_size_limit',
      ),
      rejectTxCongestionThreshold: json.valueAsDouble<double?>(
        'reject_tx_congestion_threshold',
      ),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'allowed_shard_outgoing_gas': config.encodeBigint(allowedShardOutgoingGas),
    'max_congestion_incoming_gas': config.encodeBigint(
      maxCongestionIncomingGas,
    ),
    'max_congestion_memory_consumption': config.encodeBigint(
      maxCongestionMemoryConsumption,
    ),
    'max_congestion_missed_chunks': config.encodeBigint(
      maxCongestionMissedChunks,
    ),
    'max_congestion_outgoing_gas': config.encodeBigint(
      maxCongestionOutgoingGas,
    ),
    'max_outgoing_gas': config.encodeBigint(maxOutgoingGas),
    'max_tx_gas': config.encodeBigint(maxTxGas),
    'min_outgoing_gas': config.encodeBigint(minOutgoingGas),
    'min_tx_gas': config.encodeBigint(minTxGas),
    'outgoing_receipts_big_size_limit': config.encodeBigint(
      outgoingReceiptsBigSizeLimit,
    ),
    'outgoing_receipts_usual_size_limit': config.encodeBigint(
      outgoingReceiptsUsualSizeLimit,
    ),
    'reject_tx_congestion_threshold': rejectTxCongestionThreshold,
  });
}

