/// This action allows to execute the inner actions behalf of the defined sender.
class NearRpcDelegateAction {
  /// List of actions to be executed.
  final List<NearRpcNonDelegateAction> actions;

  /// The maximal height of the block in the blockchain below which the given DelegateAction is valid.
  final BigInt maxBlockHeight;

  /// Nonce to ensure that the same delegate action is not sent twice by a
  final BigInt nonce;

  /// Public key used to sign this delegated action.
  final String publicKey;

  /// Receiver of the delegated actions.
  final String receiverId;

  /// Signer of the delegated actions
  final String senderId;

  const NearRpcDelegateAction({
    required this.actions,
    required this.maxBlockHeight,
    required this.nonce,
    required this.publicKey,
    required this.receiverId,
    required this.senderId,
  });

  factory NearRpcDelegateAction.fromJson(Map<String, dynamic> json) {
    return NearRpcDelegateAction(
      actions:
          json
              .valueEnsureAsList<dynamic>('actions')
              .map((e) => NearRpcNonDelegateAction.fromJson(e))
              .toList(),
      maxBlockHeight: json.valueAsBigInt<BigInt>('max_block_height'),
      nonce: json.valueAsBigInt<BigInt>('nonce'),
      publicKey:
          (json['public_key'] is num
              ? json['public_key'].toString()
              : json.valueAsString<String>('public_key')),
      receiverId:
          (json['receiver_id'] is num
              ? json['receiver_id'].toString()
              : json.valueAsString<String>('receiver_id')),
      senderId:
          (json['sender_id'] is num
              ? json['sender_id'].toString()
              : json.valueAsString<String>('sender_id')),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'actions': actions.map((e) => e.toJson(config: config)).toList(),
    'max_block_height': config.encodeBigint(maxBlockHeight),
    'nonce': config.encodeBigint(nonce),
    'public_key': publicKey,
    'receiver_id': receiverId,
    'sender_id': senderId,
  });
}

