/// Costs associated with an object that can only be sent over the network (and executed
/// by the receiver).
/// NOTE: `send_sir` or `send_not_sir` fees are usually burned when the item is being created.
/// And `execution` fee is burned when the item is being executed.
class NearRpcFee {
  /// Fee for executing the object.
  final BigInt execution;

  /// Fee for sending an object potentially across the shards.
  final BigInt sendNotSir;

  /// Fee for sending an object from the sender to itself, guaranteeing that it does not leave
  final BigInt sendSir;

  const NearRpcFee({
    required this.execution,
    required this.sendNotSir,
    required this.sendSir,
  });

  factory NearRpcFee.fromJson(Map<String, dynamic> json) {
    return NearRpcFee(
      execution: json.valueAsBigInt<BigInt>('execution'),
      sendNotSir: json.valueAsBigInt<BigInt>('send_not_sir'),
      sendSir: json.valueAsBigInt<BigInt>('send_sir'),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'execution': config.encodeBigint(execution),
    'send_not_sir': config.encodeBigint(sendNotSir),
    'send_sir': config.encodeBigint(sendSir),
  });
}

/// Execution outcome of the transaction and all the subsequent receipts.
/// Could be not finalized yet
class NearRpcFinalExecutionOutcomeView {
  /// The execution outcome of receipts.
  final List<NearRpcExecutionOutcomeWithIdView> receiptsOutcome;

  /// Execution status defined by chain.rs:get_final_transaction_result
  final NearRpcFinalExecutionStatus status;

  /// Signed Transaction
  final NearRpcSignedTransactionView transaction;

  /// The execution outcome of the signed transaction.
  final NearRpcExecutionOutcomeWithIdView transactionOutcome;

  const NearRpcFinalExecutionOutcomeView({
    required this.receiptsOutcome,
    required this.status,
    required this.transaction,
    required this.transactionOutcome,
  });

  factory NearRpcFinalExecutionOutcomeView.fromJson(Map<String, dynamic> json) {
    return NearRpcFinalExecutionOutcomeView(
      receiptsOutcome:
          json
              .valueEnsureAsList<Map<String, dynamic>>('receipts_outcome')
              .map((e) => NearRpcExecutionOutcomeWithIdView.fromJson(e))
              .toList(),
      status: json.valueTo<NearRpcFinalExecutionStatus, Object>(
        key: 'status',
        parse:
            (e) => NearRpcFinalExecutionStatus.fromJson(JsonParser.valueAs(e)),
      ),
      transaction: json
          .valueTo<NearRpcSignedTransactionView, Map<String, dynamic>>(
            key: 'transaction',
            parse: (v) => NearRpcSignedTransactionView.fromJson(v),
          ),
      transactionOutcome: json
          .valueTo<NearRpcExecutionOutcomeWithIdView, Map<String, dynamic>>(
            key: 'transaction_outcome',
            parse: (v) => NearRpcExecutionOutcomeWithIdView.fromJson(v),
          ),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'receipts_outcome':
        receiptsOutcome.map((e) => e.toJson(config: config)).toList(),
    'status': status.toJson(config: config),
    'transaction': transaction.toJson(config: config),
    'transaction_outcome': transactionOutcome.toJson(config: config),
  });
}

/// Final execution outcome of the transaction and all of subsequent the receipts. Also includes
/// the generated receipt.
class NearRpcFinalExecutionOutcomeWithReceiptView {
  /// Receipts generated from the transaction
  final List<NearRpcReceiptView> receipts;

  /// The execution outcome of receipts.
  final List<NearRpcExecutionOutcomeWithIdView> receiptsOutcome;

  /// Execution status defined by chain.rs:get_final_transaction_result
  final NearRpcFinalExecutionStatus status;

  /// Signed Transaction
  final NearRpcSignedTransactionView transaction;

  /// The execution outcome of the signed transaction.
  final NearRpcExecutionOutcomeWithIdView transactionOutcome;

  const NearRpcFinalExecutionOutcomeWithReceiptView({
    required this.receipts,
    required this.receiptsOutcome,
    required this.status,
    required this.transaction,
    required this.transactionOutcome,
  });

  factory NearRpcFinalExecutionOutcomeWithReceiptView.fromJson(
    Map<String, dynamic> json,
  ) {
    return NearRpcFinalExecutionOutcomeWithReceiptView(
      receipts:
          json
              .valueEnsureAsList<Map<String, dynamic>>('receipts')
              .map((e) => NearRpcReceiptView.fromJson(e))
              .toList(),
      receiptsOutcome:
          json
              .valueEnsureAsList<Map<String, dynamic>>('receipts_outcome')
              .map((e) => NearRpcExecutionOutcomeWithIdView.fromJson(e))
              .toList(),
      status: json.valueTo<NearRpcFinalExecutionStatus, Object>(
        key: 'status',
