/// Grants limited permission to make transactions with FunctionCallActions
/// The permission can limit the allowed balance to be spent on the prepaid gas.
/// It also restrict the account ID of the receiver for this function call.
/// It also can restrict the method name for the allowed function calls.
class NearRpcFunctionCallPermission {
  /// Allowance is a balance limit to use by this access key to pay for function call gas and
  final String? allowance;

  /// A list of method names that can be used. The access key only allows transactions with the
  final List<String> methodNames;

  /// The access key only allows transactions with the given receiver's account id.
  final String receiverId;

  const NearRpcFunctionCallPermission({
    this.allowance,
    required this.methodNames,
    required this.receiverId,
  });

  factory NearRpcFunctionCallPermission.fromJson(Map<String, dynamic> json) {
    return NearRpcFunctionCallPermission(
      allowance:
          (json['allowance'] is num
              ? json['allowance'].toString()
              : json.valueAsString<String?>('allowance')),
      methodNames: json.valueAsList<List<String>>('method_names'),
      receiverId:
          (json['receiver_id'] is num
              ? json['receiver_id'].toString()
              : json.valueAsString<String>('receiver_id')),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'allowance': allowance,
    'method_names': methodNames,
    'receiver_id': receiverId,
  });
}

/// Configuration for garbage collection.
class NearRpcGCConfig {
  /// Maximum number of blocks to garbage collect at every garbage collection
  final BigInt? gcBlocksLimit;

  /// Maximum number of height to go through at each garbage collection step
  final BigInt? gcForkCleanStep;

  /// Number of epochs for which we keep store data.
  final BigInt? gcNumEpochsToKeep;

  /// How often gc should be run
  final NearRpcDurationAsStdSchemaProvider? gcStepPeriod;

  const NearRpcGCConfig({
    this.gcBlocksLimit,
    this.gcForkCleanStep,
    this.gcNumEpochsToKeep,
    this.gcStepPeriod,
  });

  factory NearRpcGCConfig.fromJson(Map<String, dynamic> json) {
    return NearRpcGCConfig(
      gcBlocksLimit: json.valueAsBigInt<BigInt?>('gc_blocks_limit'),
      gcForkCleanStep: json.valueAsBigInt<BigInt?>('gc_fork_clean_step'),
      gcNumEpochsToKeep: json.valueAsBigInt<BigInt?>('gc_num_epochs_to_keep'),
      gcStepPeriod: json
          .valueTo<NearRpcDurationAsStdSchemaProvider?, Map<String, dynamic>>(
            key: 'gc_step_period',
            parse: (v) => NearRpcDurationAsStdSchemaProvider.fromJson(v),
          ),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'gc_blocks_limit': config.encodeBigint(gcBlocksLimit),
    'gc_fork_clean_step': config.encodeBigint(gcForkCleanStep),
    'gc_num_epochs_to_keep': config.encodeBigint(gcNumEpochsToKeep),
    'gc_step_period': gcStepPeriod?.toJson(config: config),
  });
}

