class NearRpcGenesisConfig {
  /// Threshold for kicking out block producers, between 0 and 100.
  final int blockProducerKickoutThreshold;

  /// ID of the blockchain. This must be unique for every blockchain.
  final String chainId;

  /// Limits the number of shard changes in chunk producer assignments,
  final BigInt? chunkProducerAssignmentChangesLimit;

  /// Threshold for kicking out chunk producers, between 0 and 100.
  final int chunkProducerKickoutThreshold;

  /// Threshold for kicking out nodes which are only chunk validators, between 0 and 100.
  final int? chunkValidatorOnlyKickoutThreshold;

  /// Enable dynamic re-sharding.
  final bool dynamicResharding;

  /// Epoch length counted in block heights.
  final BigInt epochLength;

  /// Fishermen stake threshold.
  final String fishermenThreshold;

  /// Initial gas limit.
  final BigInt gasLimit;

  /// Gas price adjustment rate
  final List<int> gasPriceAdjustmentRate;

  /// Height of genesis block.
  final BigInt genesisHeight;

  /// Official time of blockchain start.
  final String genesisTime;
  final String maxGasPrice;

  /// Maximum inflation on the total supply every epoch.
  final List<int> maxInflationRate;

  /// Max stake percentage of the validators we will kick out.
  final int? maxKickoutStakePerc;

  /// Minimum gas price. It is also the initial gas price.
  final String minGasPrice;

  /// The minimum stake required for staking is last seat price divided by this number.
  final BigInt? minimumStakeDivisor;

  /// The lowest ratio s/s_total any block producer can have.
  final List<int>? minimumStakeRatio;

  /// The minimum number of validators each shard must have
  final BigInt? minimumValidatorsPerShard;

  /// Number of block producer seats at genesis.
  final BigInt numBlockProducerSeats;

  /// Expected number of blocks per year
  final BigInt numBlocksPerYear;

  /// Number of chunk producers.
  final BigInt? numChunkProducerSeats;
  final BigInt? numChunkValidatorSeats;

  /// Online maximum threshold above which validator gets full reward.
  final List<int>? onlineMaxThreshold;

  /// Online minimum threshold below which validator doesn't receive reward.
  final List<int>? onlineMinThreshold;

  /// Protocol treasury rate
  final List<int> protocolRewardRate;

  /// Protocol treasury account
  final String protocolTreasuryAccount;

  /// Threshold of stake that needs to indicate that they ready for upgrade.
  final List<int>? protocolUpgradeStakeThreshold;

  /// Protocol version that this genesis works with.
  final int protocolVersion;

  /// Layout information regarding how to split accounts to shards
  final NearRpcShardLayout? shardLayout;

  /// If true, shuffle the chunk producers across shards. In other words, if
  final bool? shuffleShardAssignmentForChunkProducers;

  /// Number of target chunk validator mandates for each shard.
  final BigInt? targetValidatorMandatesPerShard;

  /// Total supply of tokens at genesis.
  final String totalSupply;

  /// Number of blocks for which a given transaction is valid
  final BigInt transactionValidityPeriod;

  /// This is only for test purposes. We hard code some configs for mainnet and testnet
  final bool? useProductionConfig;

  /// List of initial validators.
  final List<NearRpcAccountInfo> validators;

  const NearRpcGenesisConfig({
    required this.blockProducerKickoutThreshold,
    required this.chainId,
    this.chunkProducerAssignmentChangesLimit,
