    required this.fishermenThreshold,
    required this.gasLimit,
    required this.gasPriceAdjustmentRate,
    required this.genesisHeight,
    required this.genesisTime,
    required this.maxGasPrice,
    required this.maxInflationRate,
    this.maxKickoutStakePerc,
    required this.minGasPrice,
    this.minimumStakeDivisor,
    this.minimumStakeRatio,
    this.minimumValidatorsPerShard,
    required this.numBlockProducerSeats,
    required this.numBlocksPerYear,
    this.numChunkProducerSeats,
    this.numChunkValidatorSeats,
    this.onlineMaxThreshold,
    this.onlineMinThreshold,
    required this.protocolRewardRate,
    required this.protocolTreasuryAccount,
    this.protocolUpgradeStakeThreshold,
    required this.protocolVersion,
    this.shardLayout,
    this.shuffleShardAssignmentForChunkProducers,
    this.targetValidatorMandatesPerShard,
    required this.totalSupply,
    required this.transactionValidityPeriod,
    this.useProductionConfig,
    required this.validators,
