class NearRpcIndexerChunkView {
  final String author;
  final NearRpcChunkHeaderView header;

  /// Receipts that were processed instantly in the same chunk they were created.
  final List<NearRpcReceiptView>? instantReceipts;

  /// Receipts generated in this chunk from transactions with `signer_id`
  final List<NearRpcReceiptView>? localReceipts;

  /// Represents receipts generated by execution of the previous chunk.
  final List<NearRpcReceiptView> receipts;
  final List<NearRpcIndexerTransactionWithOutcome> transactions;

  const NearRpcIndexerChunkView({
    required this.author,
    required this.header,
    this.instantReceipts,
    this.localReceipts,
    required this.receipts,
    required this.transactions,
  });

  factory NearRpcIndexerChunkView.fromJson(Map<String, dynamic> json) {
    return NearRpcIndexerChunkView(
      author:
          (json['author'] is num
              ? json['author'].toString()
              : json.valueAsString<String>('author')),
      header: json.valueTo<NearRpcChunkHeaderView, Map<String, dynamic>>(
        key: 'header',
        parse: (v) => NearRpcChunkHeaderView.fromJson(v),
      ),
      instantReceipts:
          json.hasValue('instant_receipts')
              ? json
                  .valueEnsureAsList<Map<String, dynamic>>('instant_receipts')
                  .map((e) => NearRpcReceiptView.fromJson(e))
                  .toList()
              : null,
      localReceipts:
          json.hasValue('local_receipts')
              ? json
                  .valueEnsureAsList<Map<String, dynamic>>('local_receipts')
                  .map((e) => NearRpcReceiptView.fromJson(e))
                  .toList()
              : null,
      receipts:
          json
              .valueEnsureAsList<Map<String, dynamic>>('receipts')
              .map((e) => NearRpcReceiptView.fromJson(e))
              .toList(),
      transactions:
          json
              .valueEnsureAsList<Map<String, dynamic>>('transactions')
              .map((e) => NearRpcIndexerTransactionWithOutcome.fromJson(e))
              .toList(),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'author': author,
    'header': header.toJson(config: config),
    'instant_receipts':
        instantReceipts?.map((e) => e.toJson(config: config)).toList(),
    'local_receipts':
        localReceipts?.map((e) => e.toJson(config: config)).toList(),
    'receipts': receipts.map((e) => e.toJson(config: config)).toList(),
    'transactions': transactions.map((e) => e.toJson(config: config)).toList(),
  });
}

