/// Describes limits for VM and Runtime.
class NearRpcLimitConfig {
  /// Deprecated: full account id validation is always enforced, so this is
  final BigInt? accountIdValidityRulesVersion;

  /// The initial number of memory pages.
  final int? initialMemoryPages;

  /// Max number of actions per receipt.
  final BigInt? maxActionsPerReceipt;

  /// Max length of arguments in a function call action.
  final BigInt? maxArgumentsLength;

  /// If present, stores max total number of basic blocks across all functions in a contract.
  final BigInt? maxBlocksPerContract;

  /// If present, stores max number of basic blocks (block/loop/if) in a single function.
  final BigInt? maxBlocksPerFunction;

  /// Max contract size
  final BigInt? maxContractSize;

  /// Max number of `DeployContract` and `DeployGlobalContract` actions
  final BigInt? maxDeployActionsPerReceipt;

  /// If present, stores max number of elements in a single contract's table
  final int? maxElementsPerContractTable;

  /// If present, stores max byte size of a single function body in a contract
  final BigInt? maxFunctionBodySize;

  /// If present, stores max number of functions in one contract
  final BigInt? maxFunctionsNumberPerContract;

  /// Max amount of gas that can be used, excluding gas attached to promises.
  final BigInt? maxGasBurnt;

  /// If present, stores max number of globals (entries in the wasm global
  final BigInt? maxGlobalsPerContract;

  /// If present, stores max byte size of the wasm code after gas instrumentation.
  final BigInt? maxInstrumentedCodeSize;

  /// Max length of any method name (without terminating character).
  final BigInt? maxLengthMethodName;

  /// Max length of returned data
  final BigInt? maxLengthReturnedData;

  /// Max storage key size
  final BigInt? maxLengthStorageKey;

  /// Max storage value size
  final BigInt? maxLengthStorageValue;

  /// If present, stores max number of locals declared globally in one contract
  final BigInt? maxLocalsPerContract;

  /// What is the maximal memory pages amount is allowed to have for a contract.
  final int? maxMemoryPages;

  /// Max total length of all method names (including terminating character) for a function call
  final BigInt? maxNumberBytesMethodNames;

  /// Max number of input data dependencies
  final BigInt? maxNumberInputDataDependencies;

  /// Maximum number of log entries.
  final BigInt? maxNumberLogs;

  /// Maximum number of registers that can be used simultaneously.
  final BigInt? maxNumberRegisters;

  /// If present, stores the max operand stack size (in bytes) at any point
  final BigInt? maxOperandStackBytesPerFunction;
  final BigInt? maxParamsPerContract;
  final BigInt? maxParamsPerFunction;

  /// Max number of promises that a function call can create
  final BigInt? maxPromisesPerFunctionCallAction;

  /// Max receipt size
  final BigInt? maxReceiptSize;

  /// Max combined size (in bytes) of the resolved promise inputs a single
  final BigInt? maxReceiptTotalInputSize;

  /// Maximum number of bytes that can be stored in a single register.
  final BigInt? maxRegisterSize;

  /// How tall the stack is allowed to grow?
  final int? maxStackHeight;

  /// Max number of storage entries the `DeterministicStateInit` and
  final BigInt? maxStateInitEntries;

  /// If present, stores max number of tables declared globally in one contract
  final int? maxTablesPerContract;

  /// Maximum total length in bytes of all log messages.
  final BigInt? maxTotalLogLength;

  /// Max total prepaid gas for all function call actions per receipt.
  final BigInt? maxTotalPrepaidGas;

  /// Max transaction size
  final BigInt? maxTransactionSize;

  /// If present, stores max number of entries in the wasm type section that
  final BigInt? maxTypesPerContract;

  /// Max number of access keys the `UniversalStateInit` actions in one receipt
  final BigInt? maxUniversalStateInitKeys;

  /// Maximum number of bytes for payload passed over a yield resume.
  final BigInt? maxYieldPayloadSize;

  /// If present, requires at least this many bytes of contract code per local.
  final BigInt? minContractSizePerLocal;

  /// Hard limit on the size of storage proof generated while executing a single receipt.
  final int? perReceiptStorageProofSizeLimit;

  /// Limit of memory used by registers.
  final BigInt? registersMemoryLimit;

  /// Number of blocks after which a yielded promise times out.
  final BigInt? yieldTimeoutLengthInBlocks;

  const NearRpcLimitConfig({
    this.accountIdValidityRulesVersion,
    this.initialMemoryPages,
    this.maxActionsPerReceipt,
    this.maxArgumentsLength,
    this.maxBlocksPerContract,
    this.maxBlocksPerFunction,
    this.maxContractSize,
    this.maxDeployActionsPerReceipt,
    this.maxElementsPerContractTable,
    this.maxFunctionBodySize,
    this.maxFunctionsNumberPerContract,
    this.maxGasBurnt,
    this.maxGlobalsPerContract,
    this.maxInstrumentedCodeSize,
    this.maxLengthMethodName,
    this.maxLengthReturnedData,
    this.maxLengthStorageKey,
    this.maxLengthStorageValue,
    this.maxLocalsPerContract,
    this.maxMemoryPages,
    this.maxNumberBytesMethodNames,
    this.maxNumberInputDataDependencies,
    this.maxNumberLogs,
    this.maxNumberRegisters,
    this.maxOperandStackBytesPerFunction,
    this.maxParamsPerContract,
    this.maxParamsPerFunction,
