/// ClientConfig where some fields can be updated at runtime.
class NearRpcRpcClientConfigResponse {
  /// Not clear old data, set `true` for archive nodes.
  final bool? archive;

  /// Behind this horizon header fetch kicks in.
  final BigInt? blockHeaderFetchHorizon;

  /// Duration to check for producing / skipping block.
  final String? blockProductionTrackingDelay;

  /// How long to wait for a state sync block request response
  final List<BigInt>? blockRequestTimeout;

  /// Time between check to perform catchup.
  final List<BigInt>? catchupStepPeriod;

  /// Chain id for status.
  final String? chainId;

  /// Optional config for the Chunk Distribution Network feature.
  final NearRpcChunkDistributionNetworkConfig? chunkDistributionNetwork;

  /// Time between checking to re-request chunks.
  final List<BigInt>? chunkRequestRetryPeriod;

  /// Number of threads for ChunkValidationActor pool.
  final int? chunkValidationThreads;

  /// Multiplier for the wait time for all chunks to be received.
  final String? chunkWaitMult;

  /// Height horizon for the chunk cache. A chunk is removed from the cache
  final BigInt? chunksCacheHeightHorizon;

  /// Number of threads to execute background migration work in client.
  final int? clientBackgroundMigrationThreads;

  /// Configuration for a cloud-based archival writer. If this config is present, the writer is enabled and
  final NearRpcCloudArchivalWriterConfig? cloudArchivalWriter;

  /// If true, the node won't forward transactions to next the chunk producers.
  final bool? disableTxRouting;

  /// Time between running doomslug timer.
  final String? doomslugStepPeriod;

  /// If true, transactions for the next chunk will be prepared early, right after the previous chunk's
  final bool? enableEarlyPrepareTransactions;
  final bool? enableMultilineLogging;

  /// Re-export storage layer statistics as prometheus metrics.
  final bool? enableStatisticsExport;

  /// Epoch length.
  final BigInt? epochLength;

  /// Options for epoch sync.
  final NearRpcEpochSyncConfig? epochSync;

  /// Graceful shutdown at expected block height.
  final String? expectedShutdown;

  /// Garbage collection configuration.
  final NearRpcGCConfig? gc;

  /// Expected increase of header head height per second during header sync
  final BigInt? headerSyncExpectedHeightPerSecond;

  /// How much time to wait after initial header sync
  final List<BigInt>? headerSyncInitialTimeout;

  /// How much time to wait after some progress is made in header sync
  final List<BigInt>? headerSyncProgressTimeout;

  /// How much time to wait before banning a peer in header sync if sync is too slow
  final List<BigInt>? headerSyncStallBanTimeout;

  /// Period between logging summary information.
  final List<BigInt>? logSummaryPeriod;

  /// Enable coloring of the logs
  final NearRpcLogSummaryStyle? logSummaryStyle;

  /// Maximum wait for approvals before producing block.
  final String? maxBlockProductionDelay;

  /// Maximum duration before skipping given height.
  final String? maxBlockWaitDelay;

  /// Max burnt gas per view method.  If present, overrides value stored in
  final BigInt? maxGasBurntView;

  /// Minimum duration before producing block.
  final String? minBlockProductionDelay;

  /// Minimum number of peers to start syncing.
  final int? minNumPeers;

  /// Number of block producer seats
  final BigInt? numBlockProducerSeats;

  /// Maximum size of state witnesses in the OrphanStateWitnessPool.
  final BigInt? orphanStateWitnessMaxSize;

  /// OrphanStateWitnessPool keeps instances of ChunkStateWitness which can't be processed
  final int? orphanStateWitnessPoolSize;

  /// Limit the time of adding transactions to a chunk.
  final String? produceChunkAddTransactionsTimeLimit;

  /// Produce empty blocks, use `false` for testing.
  final bool? produceEmptyBlocks;

  /// Determines whether client should exit if the protocol version is not supported
  final NearRpcProtocolVersionCheckConfig? protocolVersionCheck;

  /// Max `±window` accepted on `EXPERIMENTAL_receipt_to_tx` requests.
  final BigInt? receiptToTxMaxHintWindow;

  /// Max block-distance ancestor scan walks per hop once any scan in
  final BigInt? receiptToTxMaxHopDistance;

  /// Per-request ceiling on outcome rows the `EXPERIMENTAL_receipt_to_tx`
  final BigInt? receiptToTxMaxOutcomesPerRequest;
  final String? reshardingConfig;

  /// Listening rpc port for status.
  final String? rpcAddr;

  /// Save observed instances of invalid ChunkStateWitness to the database in DBCol::InvalidChunkStateWitnesses.
  final bool? saveInvalidWitnesses;

  /// Save observed instances of ChunkStateWitness to the database in DBCol::LatestChunkStateWitnesses.
  final bool? saveLatestWitnesses;

  /// Whether to persist receipt-to-tx origin mappings to disk or not.
  final bool? saveReceiptToTx;

  /// Whether to persist state changes on disk or not.
  final bool? saveStateChanges;

  /// save_trie_changes should be set to true iff
  final bool? saveTrieChanges;

  /// Whether to persist transaction outcomes to disk or not.
  final bool? saveTxOutcomes;

  /// Whether to persist partial chunk parts for untracked shards or not.
  final bool? saveUntrackedPartialChunksParts;

  /// Skip waiting for sync (for testing or single node testnet).
  final bool? skipSyncWait;

  /// Number of threads for StateRequestActor pool.
  final int? stateRequestServerThreads;

  /// Number of seconds between state requests for view client.
  final List<BigInt>? stateRequestThrottlePeriod;

  /// Maximum number of state requests served per throttle period
  final int? stateRequestsPerThrottlePeriod;

  /// Options for syncing state.
  final NearRpcStateSyncConfig? stateSync;

  /// How long to wait for a response from p2p state sync
  final List<BigInt>? stateSyncP2pTimeout;

  /// How long to wait after a failed state sync request
  final List<BigInt>? stateSyncRetryBackoff;

  /// How often to check that we are not out of sync.
  final List<BigInt>? syncCheckPeriod;

  /// Sync height threshold: below this difference in height don't start syncing.
  final BigInt? syncHeightThreshold;

  /// Maximum number of block requests to send to peers to sync
  final int? syncMaxBlockRequests;

  /// While syncing, how long to check for each step.
  final List<BigInt>? syncStepPeriod;
  final NearRpcTrackedShardsConfig? trackedShardsConfig;

  /// Limit of the size of per-shard transaction pool measured in bytes. If not set, the size
  final BigInt? transactionPoolSizeLimit;

  /// TTL in blocks for gapped strict-nonce transactions in the pool. Transactions with a
  final BigInt? transactionPoolStrictNonceTtlBlocks;
  final int? transactionRequestHandlerThreads;

  /// Upper bound of the byte size of contract state that is still viewable. None is no limit
  final BigInt? trieViewerStateSizeLimit;

  /// Time to persist Accounts Id in the router without removing them.
  final List<BigInt>? ttlAccountIdRouter;

  /// If the node is not a chunk producer within that many blocks, then route
  final BigInt? txRoutingHeightHorizon;

  /// Version of the binary.
  final NearRpcVersion? version;

  /// Upper bound on the number of access keys returned by a `view_access_key_list`
  final int? viewAccessKeysLimit;

  /// Number of threads for ViewClientActor pool.
  final int? viewClientThreads;

