  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'num_shards': config.encodeBigint(numShards),
    'version': version,
  });
}

class NearRpcShardLayoutV1 {
  /// The boundary accounts are the accounts on boundaries between shards.
  final List<String> boundaryAccounts;

  /// Maps shards from the last shard layout to shards that it splits to in this shard layout,
  final List<List<BigInt>>? shardsSplitMap;

  /// Maps shard in this shard layout to their parent shard
  final List<BigInt>? toParentShardMap;

  /// Version of the shard layout, this is useful for uniquely identify the shard layout
  final int version;

  const NearRpcShardLayoutV1({
    required this.boundaryAccounts,
    this.shardsSplitMap,
    this.toParentShardMap,
    required this.version,
  });

  factory NearRpcShardLayoutV1.fromJson(Map<String, dynamic> json) {
    return NearRpcShardLayoutV1(
      boundaryAccounts: json.valueAsList<List<String>>('boundary_accounts'),
      shardsSplitMap:
          json.hasValue('shards_split_map')
              ? json
                  .valueEnsureAsList<dynamic>('shards_split_map')
                  .map(
                    (e) =>
                        (e as List)
                            .map((e) => JsonParser.valueAsBigInt<BigInt>(e))
                            .toList(),
                  )
                  .toList()
              : null,
      toParentShardMap: json.valueAsList<List<BigInt>?>('to_parent_shard_map'),
      version: json.valueAsInt<int>('version'),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'boundary_accounts': boundaryAccounts,
    'shards_split_map': shardsSplitMap,
    'to_parent_shard_map':
        toParentShardMap?.map((e) => config.encodeBigint(e)).toList(),
    'version': version,
  });
}

