/// A view of the account
class NearRpcStateChangeWithCauseViewTypeChangeChange {
  final String accountId;

  /// Liquid (non-staked) account balance, in yoctoNEAR.
  final String amount;

  /// The nonce an uninitialized account's own transactions must use, present
  final BigInt? bootstrapNonce;

  /// Hash of the deployed contract code; the all-`1`s hash when no contract is deployed.
  final String codeHash;

  /// Set when the account uses a global contract referenced by the deploying account id.
  final String? globalContractAccountId;

  /// Set when the account uses a global contract referenced by code hash.
  final String? globalContractHash;

  /// Staked balance locked for validation, in yoctoNEAR.
  final String locked;

  /// Whether the account is initialized. Only a universal account can be
  final NearRpcAccountState? state;

  final BigInt? storagePaidAt;

  /// Total storage used by the account, in bytes.
  final BigInt storageUsage;

  const NearRpcStateChangeWithCauseViewTypeChangeChange({
    required this.accountId,
    required this.amount,
    this.bootstrapNonce,
    required this.codeHash,
    this.globalContractAccountId,
    this.globalContractHash,
    required this.locked,
    this.state,
    this.storagePaidAt,
    required this.storageUsage,
  });

  factory NearRpcStateChangeWithCauseViewTypeChangeChange.fromJson(
    Map<String, dynamic> json,
  ) {
    return NearRpcStateChangeWithCauseViewTypeChangeChange(
      accountId:
          (json['account_id'] is num
              ? json['account_id'].toString()
              : json.valueAsString<String>('account_id')),
      amount:
          (json['amount'] is num
              ? json['amount'].toString()
              : json.valueAsString<String>('amount')),
      bootstrapNonce: json.valueAsBigInt<BigInt?>('bootstrap_nonce'),
      codeHash:
          (json['code_hash'] is num
              ? json['code_hash'].toString()
              : json.valueAsString<String>('code_hash')),
      globalContractAccountId:
          (json['global_contract_account_id'] is num
              ? json['global_contract_account_id'].toString()
              : json.valueAsString<String?>('global_contract_account_id')),
      globalContractHash:
          (json['global_contract_hash'] is num
              ? json['global_contract_hash'].toString()
              : json.valueAsString<String?>('global_contract_hash')),
      locked:
          (json['locked'] is num
              ? json['locked'].toString()
              : json.valueAsString<String>('locked')),
      state: json.valueTo<NearRpcAccountState?, Object>(
        key: 'state',
        parse: (e) => NearRpcAccountState.fromJson(JsonParser.valueAs(e)),
      ),
      storagePaidAt: json.valueAsBigInt<BigInt?>('storage_paid_at'),
      storageUsage: json.valueAsBigInt<BigInt>('storage_usage'),
    );
  }

  Map<String, dynamic> toJson({
    JsonifyConfig config = DefaultJsonifyConfig.defaultConfig,
  }) => config.encodeMap(<String, dynamic>{
    'account_id': accountId,
    'amount': amount,
    'bootstrap_nonce': config.encodeBigint(bootstrapNonce),
    'code_hash': codeHash,
    'global_contract_account_id': globalContractAccountId,
    'global_contract_hash': globalContractHash,
    'locked': locked,
    'state': state?.toJson(config: config),
    'storage_paid_at': config.encodeBigint(storagePaidAt),
    'storage_usage': config.encodeBigint(storageUsage),
  });
}

